-- Explicit RESTRICT keeps provenance and annotations from cascading away.
alter table simpress.configuracao add foreign key (admin_user_id) references auth.users(id) on delete restrict;
alter table simpress.estado_aplicacao add foreign key (lote_ativo_id) references simpress.lotes_inventario(id) on delete restrict;
alter table simpress.estado_aplicacao add foreign key (modelo_transferencia_id) references simpress.objetos_arquivo(id) on delete restrict;
alter table simpress.estado_aplicacao add foreign key (modelo_exportacao_id) references simpress.objetos_arquivo(id) on delete restrict;
alter table simpress.operacoes add foreign key (autor_user_id) references auth.users(id) on delete restrict;
alter table simpress.objetos_arquivo add foreign key (operacao_id) references simpress.operacoes(id) on delete restrict;
alter table simpress.arquivos_origem add foreign key (objeto_id) references simpress.objetos_arquivo(id) on delete restrict;
alter table simpress.lotes_inventario add foreign key (operacao_id) references simpress.operacoes(id) on delete restrict;
alter table simpress.lotes_inventario add foreign key (anterior_id) references simpress.lotes_inventario(id) on delete restrict;
alter table simpress.fontes_lote add foreign key (lote_id) references simpress.lotes_inventario(id) on delete restrict;
alter table simpress.fontes_lote add foreign key (arquivo_id, papel) references simpress.arquivos_origem(id, papel) on delete restrict;
alter table simpress.linhas_fonte add foreign key (lote_id, papel) references simpress.fontes_lote(lote_id, papel) on delete restrict;
alter table simpress.equipamentos_lote add foreign key (lote_id) references simpress.lotes_inventario(id) on delete restrict;
alter table simpress.equipamentos_lote add foreign key (linha_origem_id, lote_id, papel_origem) references simpress.linhas_fonte(id, lote_id, papel) on delete restrict;
alter table simpress.equipamentos_lote add foreign key (unidade_id) references simpress.unidades_catalogo(id) on delete restrict;
alter table simpress.unidades_catalogo add foreign key (origem_lote_id) references simpress.lotes_inventario(id) on delete restrict;
alter table simpress.unidades_customizadas add foreign key (unidade_id) references simpress.unidades_catalogo(id) on delete restrict;
alter table simpress.historico_apelidos add foreign key (referencia_evento_id) references simpress.historico_apelidos(evento_id) on delete restrict;
alter table simpress.historico_apelidos add foreign key (autor_user_id) references auth.users(id) on delete restrict;
alter table simpress.eventos_comparacao add foreign key (lote_id) references simpress.lotes_inventario(id) on delete restrict;
alter table simpress.eventos_comparacao add foreign key (operacao_id) references simpress.operacoes(id) on delete restrict;
alter table simpress.eventos_comparacao add foreign key (backup_anterior_id) references simpress.backups_logicos(id) on delete restrict;
alter table simpress.eventos_comparacao add foreign key (restauracao_de_evento_id) references simpress.eventos_comparacao(evento_id) on delete restrict;
alter table simpress.linhas_comparacao add foreign key (evento_id) references simpress.eventos_comparacao(evento_id) on delete restrict;
alter table simpress.anotacoes add foreign key (evento_id, item_id) references simpress.linhas_comparacao(evento_id, item_id) on delete restrict;
alter table simpress.pendencias_sincronizacao add foreign key (evento_id, item_id) references simpress.linhas_comparacao(evento_id, item_id) on delete restrict;
alter table simpress.backups_logicos add foreign key (operacao_id) references simpress.operacoes(id) on delete restrict;
alter table simpress.backups_logicos add foreign key (manifesto_objeto_id) references simpress.objetos_arquivo(id) on delete restrict;
alter table simpress.referencias_backup add foreign key (backup_id) references simpress.backups_logicos(id) on delete restrict;
alter table simpress.referencias_backup add foreign key (objeto_id) references simpress.objetos_arquivo(id) on delete restrict;
alter table simpress.conflitos_importacao add foreign key (operacao_id) references simpress.operacoes(id) on delete restrict;
alter table simpress.conflitos_importacao add foreign key (artefato_objeto_id) references simpress.objetos_arquivo(id) on delete restrict;

create index estado_lote_idx on simpress.estado_aplicacao(lote_ativo_id);
create index estado_modelo_transferencia_idx on simpress.estado_aplicacao(modelo_transferencia_id);
create index estado_modelo_exportacao_idx on simpress.estado_aplicacao(modelo_exportacao_id);
create index operacoes_recuperacao_idx on simpress.operacoes(estado, atualizado_em);
create index operacoes_autor_idx on simpress.operacoes(autor_user_id);
create index objetos_conteudo_idx on simpress.objetos_arquivo(sha256, tamanho_bytes);
create index objetos_recuperacao_idx on simpress.objetos_arquivo(estado, criado_em);
create index objetos_operacao_idx on simpress.objetos_arquivo(operacao_id);
create index arquivos_objeto_idx on simpress.arquivos_origem(objeto_id);
create index lotes_anterior_idx on simpress.lotes_inventario(anterior_id);
create index lotes_criado_idx on simpress.lotes_inventario(criado_em);
create index fontes_arquivo_idx on simpress.fontes_lote(arquivo_id, papel);
create index linhas_fonte_serie_idx on simpress.linhas_fonte(lote_id, papel, serie_normalizada);
create index equipamentos_api_idx on simpress.equipamentos_lote(lote_id, chave_api);
create index equipamentos_serie_idx on simpress.equipamentos_lote(lote_id, serie_normalizada);
create index equipamentos_origem_idx on simpress.equipamentos_lote(linha_origem_id, lote_id, papel_origem);
create index equipamentos_unidade_idx on simpress.equipamentos_lote(unidade_id);
create index unidades_source_key_idx on simpress.unidades_catalogo(source_key);
create index unidades_lote_idx on simpress.unidades_catalogo(origem_lote_id);
create index unidades_custom_source_idx on simpress.unidades_customizadas(source_key_legada);
create index apelidos_serie_idx on simpress.apelidos_manuais(serie_normalizada);
create index historico_apelidos_serie_idx on simpress.historico_apelidos(serie_normalizada, ordem_evento);
create index historico_apelidos_horario_idx on simpress.historico_apelidos(horario);
create index historico_apelidos_referencia_idx on simpress.historico_apelidos(referencia_evento_id);
create index historico_apelidos_autor_idx on simpress.historico_apelidos(autor_user_id);
create index eventos_horario_idx on simpress.eventos_comparacao(horario);
create index eventos_lote_idx on simpress.eventos_comparacao(lote_id);
create index eventos_operacao_idx on simpress.eventos_comparacao(operacao_id);
create index eventos_backup_idx on simpress.eventos_comparacao(backup_anterior_id);
create index eventos_restauracao_idx on simpress.eventos_comparacao(restauracao_de_evento_id);
create index linhas_comparacao_hash_idx on simpress.linhas_comparacao(categoria, linha_hash, evento_id);
create index linhas_comparacao_ordem_idx on simpress.linhas_comparacao(evento_id, categoria, ordem_linha);
create index pendencias_linha_idx on simpress.pendencias_sincronizacao(evento_id, item_id);
create index pendencias_recuperacao_idx on simpress.pendencias_sincronizacao(estado, proxima_tentativa_em);
create index backups_tipo_data_idx on simpress.backups_logicos(tipo, capturado_em);
create index backups_estado_data_idx on simpress.backups_logicos(estado, capturado_em);
create index backups_operacao_idx on simpress.backups_logicos(operacao_id);
create index backups_manifesto_idx on simpress.backups_logicos(manifesto_objeto_id);
create index referencias_objeto_idx on simpress.referencias_backup(objeto_id);
create index conflitos_operacao_estado_idx on simpress.conflitos_importacao(operacao_id, estado);
create index conflitos_artefato_idx on simpress.conflitos_importacao(artefato_objeto_id);
